{
  "command": "cd supabase-docker && node - <<'NODE'
const fs=require('fs'); const v={};
for(const l of fs.readFileSync('.env','utf8').split(/\r?\n/)) { if(l && !l.startsWith('#') && l.includes('=')){const i=l.indexOf('=');v[l.slice(0,i)]=l.slice(i+1)}}
if(v.JWT_SECRET.length<32 || !v.POSTGRES_PASSWORD || v.POSTGRES_PASSWORD==='your-super-secret-and-long-postgres-password' || v.DASHBOARD_PASSWORD==='this_password_is_insecure_and_should_be_updated') throw Error('secret validation failed');
if(JSON.parse(v.JWT_KEYS).length<2 || JSON.parse(v.JWT_JWKS).keys.length<2) throw Error('JWKS validation failed');
for(const k of ['ANON_KEY','SERVICE_ROLE_KEY','SUPABASE_PUBLISHABLE_KEY','SUPABASE_SECRET_KEY']) if(!v[k]) throw Error(k+' missing');
console.log('validated generated secrets, JWT/JWKS JSON, and shell scripts');
NODE
grep -qxF '.env' .gitignore && echo '.env is ignored by package .gitignore'",
  "timeout_sec": 30
}

